INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(1, 1, 31, 'Burger Bò Nướng Phô Mai Tan Chảy (Double Cheese)', 'burger-bo-nuong-pho-mai', 'Thịt bò Úc 100% nướng lửa than hoa thơm nức mũi, kẹp phô mai Cheddar béo ngậy, sốt BBQ đặc chế và rau xà lách tươi giòn.', '69000.00', '69000.00', 1, 1, 15, '2026-11-06 17:56:33', '2026-11-12 14:53:52'),
(2, 1, 31, 'Burger Bò Nướng Lửa Than Hoa (Whopper Classic)', 'burger-bo-whopper-classic', 'Thịt bò nướng lửa cỡ lớn đậm vị khói phương Tây, lát cà chua đỏ mọng và dưa chuột muối giòn tan.', '89000.00', '89000.00', 1, 1, 15, '2026-11-06 17:56:33', '2026-11-12 14:53:52'),
(3, 1, 31, 'Burger Bò Tắm Sốt Nấm Truffle Đen Thượng Hạng', 'burger-bo-sot-nam-truffle', 'Sốt kem nấm Truffle đen quý hiếm phủ trọn miếng bò nướng mọng nước, hòa quyện sốt nấm xào thơm béo.', '99000.00', '99000.00', 1, 1, 15, '2026-11-06 17:56:33', '2026-11-12 14:53:52'),
(4, 1, 31, 'Burger Bò Trứng Lòng Đào Thịt Ba Chỉ Xông Khói (Bacon)', 'burger-bo-trung-long-dao-bacon', 'Sự kết hợp hoàn hảo giữa thịt bò nướng than, trứng gà lòng đào tan chảy và 2 dải bacon áp chảo giòn rụm.', '82000.00', '82000.00', 1, 0, 15, '2026-11-06 17:56:33', '2026-11-12 14:53:52'),
(5, 1, 31, 'Burger Bò Cay Sốt Ớt Jalapeno Mễ Tây Cơ', 'burger-bo-cay-jalapeno', 'Dành cho tín đồ ăn cay! Ớt Jalapeno Mexico cay nồng kết hợp sốt chipotle mayo bốc khói kích thích vị giác.', '75000.00', '75000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(6, 1, 31, 'Burger Bò 3 Tầng Siêu Khủng (Triple Beast Burger)', 'burger-bo-3-tang-sieu-khung', '3 lớp bò Úc nướng than hoa nặng gần 400g kết hợp 3 lát phô mai Cheddar tan chảy thơm lừng ngất ngây.', '139000.00', '139000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(7, 1, 31, 'Burger Gà Phi Lê Nướng Sốt Teriyaki Mè Rang', 'burger-ga-phi-le-teriyaki', 'Thịt gà phi lê đùi rút xương ướp sốt teriyaki Nhật Bản nướng vàng óng, rắc mè trắng rang bùi thơm ngậy.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(8, 1, 31, 'Burger Cá Tuyết Phi Lê Chiên Giòn Sốt Tartar', 'burger-ca-tuyet-sot-tartar', 'Cá tuyết tươi tẩm bột xù chiên vàng rụm, thịt cá ngọt trắng mềm mịn kẹp sốt tartar chanh thì là thanh mát.', '72000.00', '72000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(9, 1, 31, 'Burger Tôm Hoàng Gia Giòn Rụm Sốt Kem Thousand Island', 'burger-tom-hoang-gia', 'Chả tôm tươi nguyên con xay dối giữ trọn độ giòn ngọt, vỏ ngoài chiên giòn tan chấm sốt nghìn hòn đảo chua béo.', '79000.00', '79000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(10, 1, 31, 'Burger Bò Sốt Phô Mai Xanh (Blue Cheese Burger)', 'burger-bo-blue-cheese', 'Vị đậm đà béo sâu đặc trưng của phô mai xanh kết hợp hành tây caramen ngọt dịu và bò nướng mọng nước.', '89000.00', '89000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(11, 1, 31, 'Combo Burger Bò Phô Mai + Khoai Tây Múi Cau + Coca-Cola', 'combo-burger-bo-khoai-coca', 'Bữa ăn chuẩn Mỹ hoàn hảo gồm 1 Burger Bò Phô Mai, 1 phần khoai tây múi cau nướng muối giòn rụm và 1 ly Coca mát lạnh.', '99000.00', '99000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(12, 1, 31, 'Combo Cặp Đôi Burger King (2 Burger Bò + 2 Khoai + 2 Nước)', 'combo-cap-doi-burger-king', 'Set ăn thịnh soạn dành cho 2 người gồm 2 Burger Bò nướng cỡ vừa, 2 phần khoai tây chiên vàng và 2 nước ngọt có ga.', '189000.00', '189000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(13, 1, 31, 'Khoai Tây Múi Cau Nướng Muối Biển & Hương Thảo', 'khoai-tay-mui-cau-nuong', 'Khoai tây cắt múi cau để vỏ nướng vàng ruộm, tẩm muối biển tinh khiết và lá hương thảo thơm lừng phong cách châu Âu.', '39000.00', '39000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(14, 1, 31, 'Khoai Tây Chiên Pháp Phủ Sốt Phô Mai Cheddar Nóng', 'khoai-tay-chien-sot-pho-mai', 'Khoai tây chiên vàng rộm ngập trong lớp sốt phô mai Cheddar nấu nóng sánh mịn, rắc thêm vụn thịt xông khói giòn tan.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(15, 1, 31, 'Vòng Hành Tây Chiên Xù Giòn Rụm (Crispy Onion Rings)', 'vong-hanh-tay-chien-xu', 'Hành tây ngọt thanh tẩm bột chiên xù vàng óng, giòn rụm bên ngoài và mềm mọng bên trong, chấm cùng sốt cocktail cay ngọt.', '35000.00', '35000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(16, 1, 31, 'Phô Mai Que Kéo Sợi Mozzarella Chiên Vàng (4 que)', 'pho-mai-que-mozzarella', 'Phô mai Mozzarella nguyên chất kéo sợi dài bất tận, vỏ bột giòn rụm chấm tương cà chua ngọt cực cuốn.', '42000.00', '42000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(17, 1, 31, 'Salad Trộn Dầu Giấm Bò Nướng BBQ Than Hoa', 'salad-tron-dau-giam-bo-nuong', 'Xà lách Romaine, cà chua bi, dưa leo và bắp ngọt trộn dầu giấm Ý, phủ những lát thịt bò nướng than hoa thơm nức.', '59000.00', '59000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(18, 1, 31, 'Bánh Táo Nướng Quế Giòn Nóng Burger King (Apple Pie)', 'banh-tao-nuong-que', 'Vỏ bánh ngàn lớp giòn tan bao bọc nhân táo tươi sốt caramel thơm lừng hương quế ấm áp, dùng nóng giòn sảng khoái.', '29000.00', '29000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(19, 1, 31, 'Trà Chanh Vàng Mật Ong Đá Xay Mát Lạnh', 'tra-chanh-vang-mat-ong', 'Thức uống giải ngấy tuyệt hảo sau khi thưởng thức burger! Chanh vàng mọng nước hòa quyện mật ong nguyên chất.', '25000.00', '25000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(20, 1, 31, 'Nước Ngọt Coca-Cola Tươi Mát Lạnh (Ly Lớn 500ml)', 'coca-cola-tuoi-mat-lanh', 'Nước ngọt có ga sảng khoái mát lạnh giúp bữa ăn thêm phần trọn vị và sảng khoái bùng nổ.', '18000.00', '18000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(21, 2, 30, 'Cơm Tấm Sườn Cốt Lết Nướng Than Hoa Bì Chả', 'com-tam-suon-bi-cha', 'Dĩa cơm tấm hạt vỡ chuẩn vị, sườn cốt lết dày dặn ướp mật ong nướng than hoa vàng óng, bì dai giòn, chả trứng hấp béo bùi.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(22, 2, 30, 'Cơm Tấm Sườn Bì Chả Trứng Ốp La (Suất Đặc Biệt)', 'com-tam-suon-bi-cha-trung-dac-biet', 'Dĩa cơm thịnh soạn đủ 4 món tinh hoa: Miếng sườn to bản nướng mềm thơm, bì thính vàng ươm, chả trứng nấm mèo và trứng ốp la lòng đào.', '65000.00', '65000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(23, 2, 30, 'Cơm Tấm Sườn Cây Khổng Lồ Nướng Mật Ong Rừng', 'com-tam-suon-cay-mat-ong', 'Cọng sườn heo tơ cây dài chọn lọc, ướp mật ong rừng hoa cà phê Đắk Lắk và nước mắm nhỉ, nướng xém cạnh thơm nức mũi.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(24, 2, 30, 'Cơm Tấm Ba Chỉ Heo Rút Sườn Nướng Giòn Da', 'com-tam-ba-chi-heo-nuong', 'Ba chỉ heo ba chỉ nạc mỡ đan xen đều đặn, nướng lửa than hoa giòn rụm phần da và mọng nước phần thịt.', '52000.00', '52000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(25, 2, 30, 'Cơm Tấm Đùi Gà Nướng Mật Ong Rừng Vàng Ruộm', 'com-tam-dui-ga-nuong-mat-ong', 'Nguyên chiếc đùi gà góc phần tư ướp gia vị cổ truyền và mật ong, nướng chín tới bóng bẩy, thịt gà mềm ngọt thơm lừng.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(26, 2, 30, 'Cơm Tấm Đùi Gà Chiên Nước Mắm Tỏi Ớt Đậm Đà', 'com-tam-dui-ga-chien-nuoc-mam', 'Đùi gà chiên lớp da giòn rụm ngào sốt nước mắm tỏi ớt kẹo sệt chua ngọt mặn mà đưa cơm vô cùng.', '58000.00', '58000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(27, 2, 30, 'Cơm Tấm Chả Cua Biển Hấp Trứng Muối', 'com-tam-cha-cua-trung-muoi', 'Chả làm từ thịt cua biển tươi, thịt heo nạc bằm, nấm mèo và lòng đỏ trứng muối bùi béo hấp cách thủy chín tới thơm lừng.', '59000.00', '59000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(28, 2, 30, 'Cơm Tấm Bò Xào Cần Tây Hành Tây Sốt Dầu Hào', 'com-tam-bo-xao-can-tay', 'Thịt bò phi lê xào lửa lớn cùng cần tây, hành tây và cà chua giòn ngọt, nước sốt bò đậm đà chan cơm tấm nóng hổi.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(29, 2, 30, 'Cơm Tấm Xíu Mại Trứng Muối Sốt Cà Chua Tươi', 'com-tam-xiu-mai-trung-muoi', 'Viên xíu mại thịt heo bằm mềm mịn ôm trọn nhân trứng muối béo ngậy, ninh trong sốt cà chua tươi sánh mịn thơm ngào ngạt.', '48000.00', '48000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(30, 2, 30, 'Cơm Tấm Thịt Ba Chỉ Kho Tàu Trứng Vịt Bùi Béo', 'com-tam-thit-kho-tau', 'Thịt heo ba chỉ kho nước dừa xiêm béo mềm tan trong miệng, miếng thịt màu cánh gián và quả trứng vịt kho thấm đượm gia vị.', '52000.00', '52000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(31, 2, 30, 'Cơm Tấm Cá Thu Kho Tiêu Tộ Đất Sài Gòn', 'com-tam-ca-thu-kho-tieu', 'Khúc cá thu tươi kho trong tộ đất với tiêu sọ Đắk Lắk cay thơm, nước cá sền sệt đậm đà chan cơm thơm ngon khó cưỡng.', '62000.00', '62000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(32, 2, 30, 'Cơm Tấm Sườn Non Rang Muối Cay Hong Kong', 'com-tam-suon-non-rang-muoi', 'Sườn non sụn giòn sần sật tẩm bột chiên vàng, xóc muối tỏi ớt rang khô đậm đà hấp dẫn vô cùng.', '68000.00', '68000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(33, 2, 30, 'Cơm Tấm Tôm Rim Thịt Ba Chỉ Đậm Đà Cơm Nhà', 'com-tam-tom-rim-ba-chi', 'Tôm đồng vỏ giòn thịt ngọt rim kẹo cùng thịt ba chỉ xắt hạt lựu, mặn mặn ngọt ngọt óng ả màu đường thốt nốt.', '58000.00', '58000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(34, 2, 30, 'Cơm Tấm Mực Nhồi Thịt Sốt Cà Chua Chua Ngọt', 'com-tam-muc-nhoi-thit', 'Mực ống tươi dày mình nhồi thịt bằm mộc nhĩ nấm hương, sốt cà chua chua thanh dậy mùi tiêu hành.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(35, 2, 30, 'Tô Canh Khổ Qua Dồn Thịt Bằm Nước Trong Thanh Mát', 'canh-kho-qua-don-thit', 'Món canh truyền thống giải nhiệt tuyệt vời! Khổ qua đắng thanh dồn thịt nạc vai xay nhuyễn, nước dùng xương hầm trong ngọt lịm.', '25000.00', '25000.00', 1, 1, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(36, 2, 30, 'Tô Canh Rong Biển Đậu Hũ Non Thịt Bằm', 'canh-rong-bien-dau-hu-non', 'Rong biển thanh mát bổ dưỡng nấu cùng đậu hũ non mềm mịn và thịt heo bằm, thơm ấm mùi gừng tươi xắt sợi.', '22000.00', '22000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(37, 2, 30, 'Tô Canh Chua Cá Hồi Lá Giang Bạc Hà Đậm Vị Nam Bộ', 'canh-chua-ca-hoi-la-giang', 'Vị chua thanh mát của lá giang và me tươi quyện vị béo ngậy của lườn cá hồi tươi, kèm đậu bắp, bạc hà, giá đỗ giòn ngọt.', '35000.00', '35000.00', 1, 0, 15, '2026-11-12 14:53:52', '2026-11-12 14:53:52'),
(38, 2, 30, 'Chả Cua Hấp Thơm Bùi Trứng Muối (Phần Thêm 1 Chiếc)', 'cha-cua-hap-phan-them', 'Phần chả cua gọi thêm cho thực khách muốn ăn thêm chả, đẫm vị thịt cua và lòng đỏ trứng muối.', '18000.00', '18000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(39, 2, 30, 'Trà Sâm Dứa Hạt É Thơm Mát Giải Nhiệt', 'tra-sam-dua-hat-e', 'Trà sâm dứa Đà Nẵng thơm nức nở kết hợp hạt é mát lành, chuẩn thức uống giải nhiệt số 1 quán cơm Sài Gòn xưa.', '15000.00', '15000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(40, 2, 30, 'Nước Mát Mía Lau Rễ Tranh Rong Biển Nấu Đường Phèn', 'nuoc-mat-mia-lau-re-tranh', 'Nước mát nấu từ mía lau, rễ tranh, lá thuốc dòi và rong biển, vị ngọt thanh mát dịu từ đường phèn tự nhiên.', '18000.00', '18000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(41, 3, 32, 'Trà Sữa Trân Châu Đường Đen Hoàng Gia (Size L)', 'tra-sua-tran-chau-hoang-gia', 'Trà đen Ceylon thơm nồng kết hợp sữa tươi thanh trùng béo nhẹ và trân châu đường đen dẻo dai nấu mới mỗi 3 tiếng.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(42, 3, 32, 'Trà Đen Alisan Macchiato Kem Muối Biển (Size L)', 'tra-alisan-macchiato', 'Trà núi cao Alisan Đài Loan nước vàng trong veo hương hoa thanh nhã, phủ lớp kem sữa phô mai mặn béo mịn màng dày 2cm.', '48000.00', '48000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(43, 3, 32, 'Trà Sữa Oolong Nướng Trân Châu Hoàng Kim (Size L)', 'tra-sua-oolong-nuong-hoang-kim', 'Lá trà Oolong sấy than hoa thơm lừng vị khói ấm áp, quyện cùng sữa béo ngọt và trân châu hoàng kim màu mật ong trong veo dai giòn.', '50000.00', '50000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(44, 3, 32, 'Trà Sữa Matcha Nhật Bản Đậu Đỏ Dẻo (Size L)', 'tra-sua-matcha-dau-do', 'Bột trà xanh Uji Kyoto nguyên chất đậm vị chát dịu kết hợp sữa béo thanh và hạt đậu đỏ Azuki ninh nhừ bùi ngọt.', '52000.00', '52000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(45, 3, 32, 'Trà Xanh Đào Dâu Tây Thạch Nha Đam Mát Lạnh (Size L)', 'tra-xanh-dao-dau-tay', 'Trà lài thơm ngát kết hợp mứt đào giòn ngọt và dâu tây tươi mọng, topping miếng đào ngâm giòn sần sật và nha đam thanh mát.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(46, 3, 32, 'Trà Xoài Nhiệt Đới Hạt Chia Kem Cheese (Size L)', 'tra-xoai-nhiet-doi-kem-cheese', 'Xoài cát chín vàng xay nhuyễn cùng trà xanh nhài thanh khiết, hạt chia giàu dinh dưỡng và lớp kem phô mai béo ngậy trên miệng ly.', '52000.00', '52000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(47, 3, 32, 'Trà Vải Lài Hoa Hồng Thanh Mát (Size L)', 'tra-vai-lai-hoa-hong', 'Hương thơm quyến rũ của cánh hoa hồng hữu cơ hòa quyện trà lài thanh tao và những trái vải thiều trắng mọng giòn ngọt.', '46000.00', '46000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(48, 3, 32, 'Trà Sữa Khoai Môn Tươi Sợi Dẻo (Taro Milk Tea)', 'tra-sua-khoai-mon-tuoi', 'Khoai môn tươi Đà Lạt hấp chín nghiền dẻo quánh, tạo nên ly trà sữa màu tím mộng mơ béo bùi tự nhiên không phẩm màu.', '48000.00', '48000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(49, 3, 32, 'Trà Sữa Thái Đỏ Kem Cheese Trân Châu Đen', 'tra-sua-thai-do-kem-cheese', 'Trà đỏ Thái Lan thơm nồng thảo mộc, sữa đặc ngọt béo ngậy và lớp kem phô mai sánh mịn phủ trên cùng.', '42000.00', '42000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(50, 3, 32, 'Trà Ô Long Bưởi Đỏ Mật Ong Rừng (Size L)', 'tra-o-long-buoi-do', 'Tép bưởi đỏ mọng nước chua thanh kết hợp trà Ô Long đậm vị và mật ong hoa cà phê, thức uống bổ sung vitamin C hoàn hảo.', '48000.00', '48000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(51, 3, 32, 'Cà Phê Muối Cố Đô Đậm Đà Kem Béo Buôn Ma Thuột', 'ca-phe-muoi-co-do', 'Cà phê Robusta Đắk Lắk nguyên chất pha phin đậm đặc, lớp kem sữa tươi đánh cùng muối biển hồng Himalaya mặn béo ngậy đỉnh cao.', '35000.00', '35000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(52, 3, 32, 'Cà Phê Cốt Dừa Đá Xay Béo Ngậy Thơm Nức', 'ca-phe-cot-dua-da-xay', 'Cốt dừa Bến Tre xay mịn cùng sữa đặc và đá tuyết, rót cà phê đen nguyên chất thơm lừng lên trên bề mặt.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(53, 3, 32, 'Americano Cam Vàng Đá Xay Thanh Mát', 'americano-cam-vang', 'Espresso nguyên chất chiết xuất áp suất cao kết hợp nước cam vàng Mỹ mọng nước và mật ong hoa rừng.', '39000.00', '39000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(54, 3, 32, 'Trà Sữa Earl Grey Bá Tước Anh Quốc (Size L)', 'tra-sua-earl-grey-ba-tuoc', 'Trà đen thượng hạng ướp tinh dầu cam Bergamot quý tộc tạo hương thơm sang trọng, vị chát êm ái quyện sữa ngậy.', '49000.00', '49000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(55, 3, 32, 'Trà Chanh Mật Ong Kim Quất Nha Đam (Size L)', 'tra-chanh-mat-ong-kim-quat', 'Chanh tươi, tắc mật ong thơm lừng kết hợp thạch nha đam thanh mát, vị chua ngọt giải nhiệt ngày hè cực đã.', '38000.00', '38000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(56, 3, 32, 'Sữa Tươi Trân Châu Đường Đen Phun Lửa (Crème Brûlée)', 'sua-tuoi-tran-chau-creme-brulee', 'Sữa tươi thanh trùng Dalat Milk kết hợp trân châu nấu đường đen dẻo nóng, mặt trên là lớp kem trứng khè lửa giòn rụm thơm mùi caramel.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(57, 3, 32, 'Sữa Chua Lắc Dâu Tây & Việt Quất Tươi', 'sua-chua-lac-dau-tay', 'Sữa chua lên men tự nhiên sánh mịn đánh cùng mứt việt quất và dâu tây Đà Lạt tươi giòn ngọt lịm.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(58, 3, 32, 'Sinh Tố Bơ Sáp Đắk Lắk Nước Cốt Dừa Thơm Béo', 'sinh-to-bo-dak-lak', 'Bơ sáp loại 1 hái tại vườn Buôn Ma Thuột, cơm bơ vàng ươm dẻo quánh xay cùng nước cốt dừa và sữa đặc béo ngậy ngất ngây.', '48000.00', '48000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(59, 3, 32, 'Trà Sữa Hokkaido Vani Caramel Béo Thơm (Size L)', 'tra-sua-hokkaido-caramel', 'Sữa bò Hokkaido Nhật Bản danh tiếng béo đậm đà kết hợp sốt caramel thơm ngọt và vani Madagascar tự nhiên.', '49000.00', '49000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(60, 3, 32, 'Bánh Bột Mì Nướng Croffle Phô Mai Trà Xanh (Croffle Matcha)', 'croffle-matcha-pho-mai', 'Bánh sừng bò ép nướng theo khuôn waffle giòn rụm bên ngoài xốp mềm bên trong, phủ sốt matcha và phô mai béo ngọt ăn kèm trà sữa.', '39000.00', '39000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(61, 4, 33, 'Pizza Hải Sản Sốt Pesto Ý Thượng Hạng (Size Vừa 9 inch)', 'pizza-hai-san-pesto', 'Tôm sú tươi giòn, mực ống tươi và nghêu biển hòa quyện cùng sốt Pesto húng tây thơm nức, ngập tràn phô mai Mozzarella kéo sợi.', '139000.00', '139000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(62, 4, 33, 'Pizza Bò Băm Nướng Phô Mai Xúc Xích BBQ (Size 9 inch)', 'pizza-bo-bam-bbq', 'Thịt bò băm ướp sốt BBQ đậm đà, xúc xích tiêu cay, nấm mỡ tươi và ớt chuông nướng giòn ngọt trên nền đế bánh xốp mềm.', '129000.00', '129000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(63, 4, 33, 'Pizza 4 Loại Phô Mai Ý Kéo Sợi (Quattro Formaggi)', 'pizza-4-loai-pho-mai', 'Đỉnh cao phô mai Ý! Sự kết hợp hoàn mỹ của Mozzarella kéo sợi, Gorgonzola thơm béo, Parmesan mặn mà và Ricotta bùi ngậy.', '145000.00', '145000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(64, 4, 33, 'Pizza Gà Nướng Nấm Rơm & Bơ Tỏi Đút Lò', 'pizza-ga-nuong-nam', 'Thịt gà nướng xé nhỏ ngấm gia vị bơ tỏi, nấm rơm tươi ngọt dịu và sốt kem trắng Alfredo béo mịn.', '119000.00', '119000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(65, 4, 33, 'Pizza Xúc Xích Ý Pepperoni Truyền Thống Nướng Giòn', 'pizza-pepperoni-truyen-thong', 'Những lát xúc xích Pepperoni bò cay đỏ au nướng cong giòn trên nền sốt cà chua San Marzano và phô mai Mozzarella.', '125000.00', '125000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(66, 4, 33, 'Pizza Dăm Bông & Dứa Kiểu Hawaii (Hawaiian Pizza)', 'pizza-hawaiian-dam-bong-dua', 'Vị ngọt thanh mọng nước của từng lát dứa mật kết hợp thịt dăm bông hun khói và sốt cà chua truyền thống dễ ăn cực kỳ.', '119000.00', '119000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(67, 4, 33, 'Pizza Tôm Càng Sốt Bơ Tỏi Chanh Vàng Đút Lò', 'pizza-tom-cang-bo-toi', 'Tôm càng tuyển chọn tươi sống áp chảo bơ tỏi thơm ngào ngạt, rưới chút chanh vàng Ý và phủ phô mai vàng óng.', '159000.00', '159000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(68, 4, 33, 'Pizza Nấm Truffle & Rau Chân Vịt (Pizza Chay Ý)', 'pizza-nam-truffle-chay', 'Lựa chọn thanh đạm sang trọng với nấm mỡ, nấm đông cô, rau bina chân vịt tươi và sốt nấm Truffle đen quý phái.', '135000.00', '135000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(69, 4, 33, 'Pizza Thịt Heo Xông Khói & Phô Mai Cheddar Vàng', 'pizza-bacon-cheddar', 'Dải thịt ba chỉ xông khói áp chảo giòn thơm ngập trong sốt phô mai Cheddar béo ngậy và hành tây ngọt dịu.', '129000.00', '129000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(70, 4, 33, 'Pizza Calzone Bánh Gối Ý Gấp Nửa Nhân Bò Băm Phô Mai', 'pizza-calzone-banh-goi-y', 'Pizza cuộn hình bán nguyệt truyền thống vùng Napoli, cắn vỡ lớp vỏ bánh giòn tan là dòng phô mai và thịt bò sốt cà chảy tràn.', '119000.00', '119000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(71, 4, 33, 'Mì Ý Spaghetti Bò Băm Sốt Cà Chua (Bolognese)', 'spaghetti-bo-bam-bolognese', 'Sợi mì Ý luộc chuẩn Al Dente dai mềm, sốt bò băm hầm kỹ cùng rượu vang đỏ và cà chua bi Ý ngọt lành, rắc bột phô mai thơm phức.', '79000.00', '79000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(72, 4, 33, 'Mì Ý Sốt Kem Hải Sản Carbonara Tôm Mực Nấm', 'spaghetti-hai-san-carbonara', 'Sốt kem tươi nấu cùng lòng đỏ trứng gà béo ngậy, tôm sú giòn ngọt và mực ống tươi đảo cùng nấm mỡ xào bơ tỏi.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(73, 4, 33, 'Nui Ống Xoắn Đút Lò Phô Mai Mozzarella Vàng Ruộm', 'nui-dut-lo-pho-mai', 'Nui ống ngấm sốt bò bằm cà chua, mặt trên phủ kín lớp phô mai Mozzarella đút lò vàng xém thơm lừng kéo sợi hấp dẫn.', '75000.00', '75000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(74, 4, 33, 'Bánh Mì Bơ Tỏi Nướng Giòn Kiểu Pháp (Garlic Bread)', 'banh-mi-bo-toi-phap', 'Bánh mì baguette nướng giòn rụm phết bơ lạt nguyên chất quyện tỏi bằm và lá mùi tây thơm ngát quyến rũ.', '32000.00', '32000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(75, 4, 33, 'Cánh Gà Nướng Sốt BBQ Mật Ong (6 miếng)', 'canh-ga-nuong-bbq-mat-ong', 'Cánh gà giữa tẩm ướp sốt BBQ mật ong đậm vị khói nướng trong lò đá, da gà vàng bóng óng ả thơm lừng.', '69000.00', '69000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(76, 4, 33, 'Mực Vòng Chiên Giòn Calamari Sốt Tartar Ý', 'muc-vong-calamari-chot-tartar', 'Từng khoanh mực tươi tẩm bột chiên giòn rụm bên ngoài nhưng bên trong mực vẫn mềm mọng nước, chấm cùng sốt tartar chanh tươi.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(77, 4, 33, 'Khoai Tây Chiên Phủ Phô Mai & Bột Thảo Mộc Đút Lò', 'khoai-tay-phu-pho-mai-dut-lo', 'Khoai tây cọng lớn chiên vàng ươm, đút lò cùng phô mai Mozzarella và rắc lá thơm oregano chuẩn vị Ý.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(78, 4, 33, 'Salad Rau Trộn Kiểu Caesar với Ức Gà Nướng & Phô Mai', 'salad-caesar-uc-ga', 'Xà lách Romaine tươi giòn trộn sốt Caesar cá cơm truyền thống, bánh mì nướng giòn vụn, phô mai Parmesan và ức gà nướng áp chảo.', '59000.00', '59000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(79, 4, 33, 'Bánh Lava Socola Đút Lò Tan Chảy Kem Vani Lạnh', 'banh-lava-socola-kem-vani', 'Món tráng miệng Ý quyến rũ! Xắn nhẹ lớp bánh nướng là dòng socola đen Bỉ ấm nóng tan chảy, ăn cùng viên kem vani mát lạnh tương phản.', '49000.00', '49000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(80, 4, 33, 'Nước Ngọt Pepsi Tươi Có Ga Mát Lạnh (Ly Lớn 500ml)', 'pepsi-tuoi-mat-lanh', 'Thức uống có ga kinh điển giúp cân bằng vị giác và thưởng thức trọn vẹn những miếng pizza phô mai béo ngậy.', '18000.00', '18000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(81, 5, 30, 'Phở Bò Tái Nạm Nước Dùng Ninh Xương Ống 18 Tiếng', 'pho-bo-tai-nam', 'Nước dùng trong veo ninh từ xương ống bò Úc cùng hoa hồi, quế chi, thảo quả 18 tiếng ngọt thanh không mì chính. Bò tái mềm mọng, nạm bò giòn béo thơm lừng.', '69000.00', '69000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(82, 5, 30, 'Phở Bò Tái Lăn Áp Chảo Thơm Lừng Tỏi Gừng', 'pho-bo-tai-lan-ap-chao', 'Thịt bò bắp thái mỏng lăn áp chảo trên lửa bùng cùng tỏi đập dập và gừng già, trút lên bát phở thơm ngút ngàn dậy vị Bắc.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(83, 5, 30, 'Bát Phở Bò Đặc Biệt (Tái, Nạm, Gầu, Gân, Bò Viên)', 'pho-bo-dac-biet-thap-cam', 'Tô phở thịnh soạn ngập tràn 5 loại thịt bò hảo hạng: Thịt bò tái mềm ngọt, nạm giòn, gầu béo ngậy, gân trong dẻo giòn và bò viên gân sần sật.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(84, 5, 30, 'Phở Gầu Giòn Béo Ngậy Ninh Thảo Mộc', 'pho-gau-gion-thao-moc', 'Miếng gầu bò có lớp mỡ trắng giòn sần sật không hề ngấy, quyện cùng nước dùng nóng rẫy đậm đà thảo mộc phương Bắc.', '72000.00', '72000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(85, 5, 30, 'Phở Bắp Bò Hoa Tươi Nhúng Tái Mềm Ngọt', 'pho-bap-bo-hoa-nhung', 'Bắp bò hoa thái mỏng như cánh lụa, nhúng vừa chín tới giữ trọn từng đường gân hoa giòn rụm và vị ngọt tự nhiên của thịt bò tươi.', '78000.00', '78000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(86, 5, 30, 'Phở Bò Sốt Vang Rượu Đỏ Rực Màu Gấc Hà Nội', 'pho-bo-sot-vang-ha-noi', 'Dẻ sườn bò và gân bò hầm nhừ cùng rượu vang đỏ, hạt tiêu và sốt gấc đỏ au sánh mịn, vị thơm lừng ấm áp cực kỳ cuốn hút.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(87, 5, 30, 'Phở Đuôi Bò Hầm Thuốc Bắc Bổ Dưỡng Đại Bổ', 'pho-duoi-bo-ham-thuoc-bac', 'Khúc đuôi bò hầm cùng kỷ tử, đương quy, táo đỏ và hạt sen trong nhiều giờ, lớp da dẻo ngậy giòn sần sật đại bổ dưỡng.', '95000.00', '95000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(88, 5, 30, 'Phở Gân Bò Hầm Dẻo Giòn Sần Sật', 'pho-gan-bo-ham-deo', 'Gân bò tươi làm sạch ninh vừa độ, trong suốt như ngọc, dẻo mềm nhưng cắn vào vẫn có độ giòn sần sật thú vị.', '68000.00', '68000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(89, 5, 30, 'Phở Gà Ta Thả Vườn Xé Phay Lá Chanh Tươi', 'pho-ga-ta-xe-phay', 'Thịt gà ta thả vườn Đắk Lắk da vàng ươm giòn sần sật, thịt ngọt thơm xé phay rắc lá chanh bắc thái chỉ, nước dùng gà thanh khiết.', '65000.00', '65000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(90, 5, 30, 'Phở Đùi Gà Ta Chặt Miếng Chấm Muối Tiêu Chanh', 'pho-dui-ga-ta-chat', 'Nguyên chiếc đùi gà ta chặt miếng bày đẹp mắt trên tô phở, chấm đĩa muối tiêu chanh ớt hiểm cay nồng xuýt xoa.', '75000.00', '75000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(91, 5, 30, 'Phở Trộn Bò Nướng Tỏi Ớt & Đậu Phộng Rang (Phở Khô)', 'pho-tron-bo-nuong', 'Bánh phở tươi trộn sốt chua ngọt đặc chế, thịt bò xào tỏi thơm phức, rau thơm, giá đỗ, hành phi và đậu phộng rang giòn thơm, kèm bát nước dùng con.', '68000.00', '68000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(92, 5, 30, 'Phở Xào Bò Cải Ngọt Giòn Rụm Lửa Lớn', 'pho-xao-bo-cai-ngot', 'Bánh phở áp chảo cháy cạnh thơm mùi khói chảo gang, xào cùng thịt bò bắp mọng nước và cải ngọt xanh non mướt mát.', '75000.00', '75000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(93, 5, 30, 'Phở Cuốn Bò Xào Rau Thơm Nước Chấm Tỏi Ớt (5 chiếc)', 'pho-cuon-bo-xao-ha-noi', 'Bánh phở tráng mỏng mềm mướt cuốn cùng thịt bò xào gừng tỏi, rau xà lách, rau mùi húng láng, chấm nước mắm chua ngọt đu đủ giòn.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(94, 5, 30, 'Bánh Phở Chiên Phồng Xốt Thịt Bò Cải Xanh', 'banh-pho-chien-phong-sot-bo', 'Từng miếng bánh phở vuông vức chiên phồng xốp giòn rụm như bánh phồng tôm, rưới sốt thịt bò xào cải xanh sánh vàng óng ả.', '79000.00', '79000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(95, 5, 30, 'Bát Tiết Hầm Trứng Gà Ta Lòng Đào Hành Trần', 'tiet-ham-trung-ga-ta', 'Tiết bò mềm mướt không tanh hầm trong nước dùng phở bò ngọt lịm, kèm 1 quả trứng gà ta trần lòng đào béo ngậy và hành hoa.', '25000.00', '25000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(96, 5, 30, 'Chén Tủy Bò Béo Ngậy Hành Trần Tiêu Sọ', 'chen-tuy-bo-beo-ngay', 'Tủy bò tươi lấy từ xương ống hầm béo ngậy, trần tái lăn cùng hành lá và hạt tiêu sọ Đắk Lắk thơm cay ấm nồng.', '30000.00', '30000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(97, 5, 30, 'Quẩy Giòn Rụm Chiên Mới Ăn Kèm Phở (Phần 4 chiếc)', 'quay-gion-rum-an-pho', 'Quẩy vàng ruộm chiên nóng giòn xốp rụm, nhúng ngập vào nước dùng phở bò hút trọn tinh hoa nước hầm xương thơm ngọt.', '12000.00', '12000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(98, 5, 30, 'Trứng Gà Ta Trần Nước Dùng Phở (1 quả lòng đào)', 'trung-ga-ta-tran-long-dao', 'Quả trứng gà ta nuôi thả tự nhiên trần vào nồi nước dùng sôi sùng sục, lòng trắng vừa chín tới, lòng đỏ béo dẻo tan trên đầu lưỡi.', '8000.00', '8000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(99, 5, 30, 'Trà Đá Hoa Nhài Chuẩn Vị Bắc Thơm Ngát', 'tra-da-hoa-nhai-vi-bac', 'Trà búp Thái Nguyên ướp hoa nhài tươi tự nhiên, chát dịu hậu ngọt sâu và mát lạnh thơm ngát sau khi ăn bát phở nóng.', '8000.00', '8000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(100, 5, 30, 'Sữa Đậu Nành Nấu Lá Dứa Nguyên Chất (Nóng / Đá)', 'sua-dau-nanh-la-dua', 'Đậu nành hạt tuyển chọn xay nấu thủ công cùng lá dứa thơm, không chất bảo quản, sánh mịn béo bùi thanh ngọt.', '15000.00', '15000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(101, 6, 37, 'Sushi Cá Hồi Cuộn Bơ Sáp & Trứng Cá Chuồn (8 khoanh)', 'sushi-ca-hoi-cuon-bo', 'Cá hồi Na Uy tươi nhập khẩu trong ngày cuộn cùng bơ sáp Đắk Lắk dẻo bùi, phủ trứng cá chuồn đỏ cam nổ lách tách trong miệng.', '89000.00', '89000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(102, 6, 37, 'Sashimi Cá Hồi Tươi Na Uy Thượng Hạng (5 lát dày)', 'sashimi-ca-hoi-na-uy', 'Từng lát cá hồi tươi sống cắt lát dày béo ngậy vân mỡ cẩm thạch trắng tuyết, ngọt tan trên đầu lưỡi, chuẩn ăn tươi sashimi Nhật.', '119000.00', '119000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(103, 6, 37, 'Sashimi Cá Ngừ Đại Dương Phú Yên Tươi Sống (5 lát)', 'sashimi-ca-ngu-dai-duong', 'Cá ngừ đại dương đỏ au màu ngọc bích, thịt săn chắc ngọt thơm giàu đạm omega-3, chấm mù tạt wasabi cay nồng bốc mũi.', '109000.00', '109000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(104, 6, 37, 'Combo Sushi Tổng Hợp Tokyo Thượng Hạng (12 miếng)', 'combo-sushi-tokyo-12-mieng', 'Set sushi đầy đặn gồm: Nigiri cá hồi, Nigiri cá ngừ, Nigiri tôm sú luộc, Nigiri bạch tuộc, Gunkan trứng cá chuồn và 6 khoanh cơm cuộn bơ cá hồi.', '169000.00', '169000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(105, 6, 37, 'Cơm Cuộn California Roll Phủ Trứng Tôm (8 khoanh)', 'california-roll-trung-tom', 'Thanh cua Nhật, dưa leo giòn mát và bơ sáp cuộn ngược rắc ngập tràn trứng tôm giòn bùi, chấm sốt mayonnaise ngọt dịu.', '79000.00', '79000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(106, 6, 37, 'Maki Tôm Chiên Giòn Tempura Sốt Mù Tạt Ngọt (8 khoanh)', 'maki-tom-chien-tempura', 'Tôm sú tươi tẩm bột tempura Nhật Bản chiên xù vàng rụm giòn tan, cuộn cơm dẻo rưới sốt teriyaki và sốt mù tạt mật ong ngọt cay nhẹ.', '85000.00', '85000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(107, 6, 37, 'Nigiri Bò Wagyu Khè Lửa Sốt Teriyaki (4 miếng)', 'nigiri-bo-wagyu-khe-lua', 'Thịt bò Wagyu vân mỡ cẩm thạch khè lửa tái chín tới tỏa hương thơm bơ ngất ngây, rưới sốt teriyaki và rắc tỏi phi giòn tan.', '119000.00', '119000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(108, 6, 37, 'Nigiri Lươn Nhật Nướng Unagi Sốt Đậm Đà (4 miếng)', 'nigiri-luon-nhat-unagi', 'Lươn Nhật rút xương nướng than hoa phết sốt Unagi Kabayaki óng ả màu hổ phách, thịt lươn béo mềm tan biến trong miệng.', '99000.00', '99000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(109, 6, 37, 'Gunkan Trứng Cá Hồi Đỏ Ikura Cao Cấp (2 miếng)', 'gunkan-trung-ca-hoi-ikura', 'Thuyền rong biển ôm trọn những viên trứng cá hồi Na Uy to tròn óng ánh như hạt ngọc ruby, vỡ tung vị mặn ngọt tươi nguyên của biển cả.', '89000.00', '89000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(110, 6, 37, 'Cơm Cuộn Da Cá Hồi Chiên Giòn Sốt Spicy Mayo (8 khoanh)', 'cuon-da-ca-hoi-chien-gion', 'Da cá hồi tẩm muối tiêu chiên giòn tan rụm cuộn cùng rau xà lách tươi và sốt cay béo, trải nghiệm giòn rụm khó quên.', '75000.00', '75000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(111, 6, 37, 'Mì Udon Xào Hải Sản Nhật Bản Sốt Dầu Hào Thơm Nức', 'mi-udon-xao-hai-san', 'Sợi mì Udon cọng tròn to trắng muốt dẻo dai xào lửa lớn cùng tôm sú, mực ống, bắp cải tím, nấm hương và rắc cá ngừ bào Katsuobushi.', '85000.00', '85000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(112, 6, 37, 'Mì Ramen Xương Heo Hầm Tonkotsu Thịt Chashu', 'mi-ramen-tonkotsu-chashu', 'Nước dùng hầm từ xương ống heo 14 tiếng sánh trắng sữa béo ngậy, sợi mì ramen tươi, lát thịt Chashu cuộn nướng mềm rục và trứng ngâm tương lòng đào.', '89000.00', '89000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(113, 6, 37, 'Cơm Bò Xào Hành Tây Kiểu Nhật Bản (Gyudon)', 'com-bo-gyudon-nhat-ban', 'Thịt bò Mỹ thái mỏng xào cùng hành tây ngọt thanh trong nước tương dashi và rượu mirin, phủ lên bát cơm dẻo nóng hổi kèm trứng gà trần onsen.', '79000.00', '79000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(114, 6, 37, 'Cơm Lươn Nhật Nướng Than Hoa Sốt Teriyaki (Unadon)', 'com-luon-unadon-nhat', 'Miếng lươn Nhật lớn nướng than hoa đượm khói, tẩm đẫm nước sốt lươn mặn ngọt óng ánh đặt trên bát cơm hạt ngọc Nhật dẻo bùi.', '139000.00', '139000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(115, 6, 37, 'Salad Rong Biển Trứng Tôm Sốt Mè Rang Nhật Bản', 'salad-rong-bien-trung-tom', 'Rong biển xanh tươi tẩm gia vị mè cay nhẹ, dưa leo xắt sợi, trứng tôm giòn sần sật trộn cùng nước sốt mè rang Kewpie thơm béo.', '49000.00', '49000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(116, 6, 37, 'Đậu Nành Nhật Bản Edamame Luộc Muối Hạt', 'dau-nanh-nhat-edamame', 'Những quả đậu nành xanh mướt luộc vừa chín tới rắc muối biển hạt tinh khiết, bóp nhẹ vỏ thưởng thức hạt đậu bùi béo ngọt lành.', '35000.00', '35000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(117, 6, 37, 'Bánh Xèo Nhật Bản Okonomiyaki Phủ Cá Ngừ Bào Nhảy Múa', 'banh-xeo-okonomiyaki-nhat', 'Bánh xèo bột mì bắp cải ngọt giòn nhân tôm thịt, rưới sốt Otafuku nâu bóng, sốt mayonnaise zic-zac và phủ đầy lớp cá ngừ bào bốc khói nhảy múa.', '59000.00', '59000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(118, 6, 37, 'Chén Canh Rong Biển Đậu Hũ Non Súp Miso Nóng Hổi', 'sup-miso-rong-bien', 'Tương đậu nành Miso trắng lên men tự nhiên nấu cùng rong biển wakame mướt mát và đậu hũ non mềm tan xắt hạt lựu.', '20000.00', '20000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(119, 6, 37, 'Trà Xanh Gạo Lứt Rang Genmaicha Nhật Bản (Ấm / Ly)', 'tra-gao-lut-genmaicha', 'Lá trà xanh búp non sao cùng gạo lứt rang nở hoa thơm nức mũi, vị thanh tao hỗ trợ tiêu hóa sau bữa ăn sushi tuyệt hảo.', '25000.00', '25000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(120, 6, 37, 'Kem Trà Xanh Matcha Nhật Bản Đậu Đỏ Dẻo (1 viên)', 'kem-matcha-dau-do-nhat', 'Viên kem matcha béo mịn đượm vị đắng thanh quý phái từ trà xanh Kyoto, điểm xuyết hạt đậu đỏ ngọt bùi dẻo thơm.', '29000.00', '29000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(121, 7, 31, 'Burger Gà Giòn Sốt Bơ Tỏi Đặc Biệt (Crispy Chicken)', 'burger-ga-gion-sot-bo', 'Đùi gà phi lê tẩm bột chiên vàng rụm lớp vỏ xù, đẫm sốt bơ tỏi thơm ngậy đặc chế, rau xà lách tươi giòn kẹp bánh mì nướng nóng.', '39000.00', '39000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(122, 7, 31, 'Burger Gà Giòn Cay Sốt Tabasco Mayonnaise', 'burger-ga-cay-tabasco', 'Thịt gà phi lê chiên giòn cay rực lửa, hòa quyện sốt béo mayo và ớt đỏ nồng nàn dành riêng cho người mê ăn cay.', '45000.00', '45000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(123, 7, 31, 'Burger Gà Nướng Phô Mai Tan Chảy Kéo Sợi', 'burger-ga-nuong-pho-mai', 'Thịt gà nướng mật ong mềm mọng nước, kẹp 2 lát phô mai Mozzarella chảy tràn thơm béo hấp dẫn.', '48000.00', '48000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(124, 7, 31, 'Burger Gà Không Xương Sốt Mật Ong Mù Tạt Vàng (Honey Mustard)', 'burger-ga-honey-mustard', 'Miếng phi lê gà chiên vàng ươm tắm sốt mù tạt mật ong thơm nồng chua ngọt kiểu Mỹ cực bắt vị.', '45000.00', '45000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(125, 7, 31, 'Burger Gà 2 Tầng Siêu Khổng Lồ (Double Crispy Monster)', 'burger-ga-2-tang-khong-lo', '2 miếng phi lê gà chiên xù khổng lồ kẹp cùng 2 lát phô mai và sốt bơ tỏi, no nê bùng nổ năng lượng.', '79000.00', '79000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(126, 7, 31, 'Burger Gà Teriyaki Kiểu Nhật Rong Biển Sấy', 'burger-ga-teriyaki-rong-bien', 'Thịt gà áp chảo sốt teriyaki mặn ngọt óng ánh, phủ lớp rong biển sợi giòn tan và hạt mè trắng bùi thơm.', '49000.00', '49000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(127, 7, 31, '2 Miếng Gà Rán Giòn Cay Truyền Thống Vàng Óng', '2-mieng-ga-ran-gion-cay', '2 miếng gà lớn (1 đùi + 1 má đùi) tẩm ướp 11 loại gia vị bí truyền, chiên áp suất vàng rộm giòn tan rụm từng thớ thịt mọng nước.', '65000.00', '65000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(128, 7, 31, '3 Miếng Đùi Gà Rán Giòn Rụm Lớp Vỏ Vàng Ruộm', '3-mieng-dui-ga-ran', 'Set 3 chiếc đùi tỏi gà to mập chiên giòn nóng hổi, vỏ ngoài giòn rụm bên trong thịt mềm thơm ngọt tự nhiên.', '95000.00', '95000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(129, 7, 31, 'Cánh Gà Lắc Phô Mai Béo Bùi Vỏ Giòn (Hộp 4 cánh)', 'canh-ga-lac-pho-mai', 'Cánh gà chiên giòn tan lắc đều bột phô mai cam thơm bùi ngọt mặn kích thích vị giác cực kỳ.', '68000.00', '68000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(130, 7, 31, 'Cánh Gà Sốt Bơ Tỏi Cay Kiểu Hàn Quốc (4 cánh)', 'canh-ga-sot-bo-toi-cay', 'Cánh gà chiên giòn đảo trên chảo ngập sốt bơ tỏi ớt gochujang cay ngọt đậm đà rắc vừng rang thơm lừng.', '72000.00', '72000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(131, 7, 31, 'Gà Popcorn Viên Chiên Giòn Lắc Rong Biển (Hộp Lớn)', 'ga-popcorn-lac-rong-bien', 'Từng viên ức gà không xương tẩm bột bắp chiên giòn rụm vừa miệng ăn, lắc cùng bột rong biển sấy thơm nức nở.', '45000.00', '45000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(132, 7, 31, 'Gà Miếng Không Xương Chiên Giòn Nuggets (6 miếng)', 'ga-mieng-nuggets-6-mieng', 'Thịt gà xay nhuyễn tẩm gia vị truyền thống chiên giòn vàng đều, món ăn khoái khẩu của cả người lớn và trẻ nhỏ.', '42000.00', '42000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(133, 7, 31, 'Combo 1 Người: 1 Burger Gà Giòn + 1 Miếng Gà + 1 Nước', 'combo-1-nguoi-burger-ga', 'Bữa ăn đầy đủ no bụng gồm 1 Burger gà sốt bơ, 1 miếng gà rán giòn cay và 1 ly Pepsi tươi có ga mát lạnh.', '85000.00', '85000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(134, 7, 31, 'Combo Gia Đình Gà Rán (4 Miếng Gà + 2 Burger + Khoai + 2 Nước)', 'combo-gia-dinh-ga-ran', 'Đại tiệc gà rán thịnh soạn cho cả nhà thưởng thức sum vầy cuối tuần với ngập tràn món ngon giòn rụm.', '199000.00', '199000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(135, 7, 31, 'Khoai Tây Chiên Lắc Phô Mai Cay Kiểu Pháp', 'khoai-tay-lac-pho-mai-cay', 'Khoai tây cọng chiên vàng giòn rụm lắc ngập bột phô mai pha ớt bột Hàn Quốc cay the the béo bùi.', '35000.00', '35000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(136, 7, 31, 'Bắp Cải Trộn Salad Coleslaw Thanh Mát Sốt Mayo', 'salad-bap-cai-coleslaw', 'Bắp cải trắng, bắp cải tím và cà rốt bào sợi giòn sần sật trộn sốt mayonnaise chua béo thanh mát giải ngấy món gà rán.', '25000.00', '25000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(137, 7, 31, 'Khoai Tây Nghiền Sốt Nâu Gravy Béo Ngậy Đậm Đà', 'khoai-tay-nghien-sot-gravy', 'Khoai tây hấp chín nghiền mịn như kem cùng bơ lạt và sữa tươi, rưới nước sốt nâu gravy hầm từ thịt gà đậm đà thơm ấm.', '28000.00', '28000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(138, 7, 31, 'Bánh Mì Cuộn Gà Giòn Sốt Caesar Phô Mai (Chicken Twister)', 'banh-mi-cuon-ga-gion-twister', 'Vỏ bánh tortilla nướng mềm cuộn chặt miếng gà giòn rụm không xương, rau xà lách, cà chua bi và sốt Caesar phô mai thơm phức.', '49000.00', '49000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(139, 7, 31, 'Trà Đào Sả Tắc Mát Lạnh Sảng Khoái (Ly Lớn)', 'tra-dao-sa-tac-mat-lanh', 'Trà đen thơm lừng hương sả đập dập, chua thanh của quất tắc và ngọt ngào của đào ngâm giòn sần sật xua tan cơn khát tức thì.', '28000.00', '28000.00', 1, 1, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(140, 7, 31, 'Trà Chanh Giã Tay Quảng Đông Thơm Nồng Mùi Tinh Dầu', 'tra-chanh-gia-tay-quang-dong', 'Chanh nước hoa Quảng Đông giã tay nát bung tinh dầu thơm ngát kết hợp cốt trà Ô long đậm đặc và đá tuyết mát lạnh sảng khoái.', '25000.00', '25000.00', 1, 0, 10, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(141, 8, 34, 'Bánh Croissant Bơ Pháp Nướng Giòn Thơm Bơ Elle & Vire', 'croissant-bo-phap', 'Chiếc bánh sừng bò chuẩn kỹ thuật Pháp ngàn lớp vỏ mỏng tang giòn rụm bên ngoài, ruột xốp tổ ong mềm mướt thơm ngát bơ tươi hảo hạng.', '35000.00', '35000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(142, 8, 34, 'Bánh Pain Au Chocolat Nhân Socola Bỉ Đắng Ngọt', 'pain-au-chocolat-bi', 'Vỏ bột ngàn lớp nướng nở phồng ôm trọn 2 thanh socola đen Bỉ 70% cacao tan chảy ấm áp quyến rũ ngất ngây.', '39000.00', '39000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(143, 8, 34, 'Bánh Sừng Bò Nhân Trứng Muối Tan Chảy Hoàng Kim', 'croissant-trung-muoi-tan-chay', 'Dòng sốt kem trứng muối lava vàng óng tan chảy bùi ngậy tuôn trào khi bẻ đôi chiếc bánh sừng bò giòn tan nóng hổi.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(144, 8, 34, 'Bánh Mousse Dâu Tây Tươi Kem Mascarpone Pháp', 'mousse-dau-tay-kem-phap', 'Lớp kem mousse mịn màng màu hồng pastel mát lạnh tan ngay trong miệng, vị chua ngọt thanh tao từ dâu tây tươi và phô mai Mascarpone.', '55000.00', '55000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(145, 8, 34, 'Bánh Tiramisu Ý Truyền Thống Cacao Cà Phê Rượu Rum', 'tiramisu-y-truyen-thong', 'Bánh sâm-panh nhúng đẫm cà phê espresso Buôn Ma Thuột hòa chút rượu rum thơm nồng, xen kẽ kem phô mai béo ngậy phủ bột cacao đắng mịn.', '52000.00', '52000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(146, 8, 34, 'Bánh Phô Mai Nướng Cháy Basque Burnt Cheesecake', 'basque-burnt-cheesecake', 'Bánh phô mai nướng nhiệt độ cao tạo lớp vỏ ngoài cháy xém màu caramel nồng nàn, bên trong lõi kem phô mai sánh dẻo béo ngậy tan chảy.', '58000.00', '58000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(147, 8, 34, 'Bánh Su Kem Vani Vỏ Giòn Craquelin (Hộp 4 chiếc)', 'su-kem-vani-vo-gion', 'Vỏ bánh nướng phủ lớp đường giòn rụm Craquelin nứt hoa văn đẹp mắt, bơm ngập nhân kem sữa tươi vani ngọt mát béo ngậy.', '36000.00', '36000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(148, 8, 34, 'Bánh Tart Trứng Bồ Đào Nha Nướng Cháy Xém (2 chiếc)', 'tart-trung-bo-dao-nha', 'Vỏ tart xếp lớp giòn rụm ngàn cánh ôm trọn phần kem trứng sữa nướng phồng xém mặt thơm nức mùi caramen béo ngậy.', '32000.00', '32000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(149, 8, 34, 'Bánh Donut Phủ Socola Bỉ Rắc Hạt Hạnh Nhân Nướng', 'donut-socola-hanh-nhan', 'Chiếc bánh donut vòng tròn mềm xốp thơm bơ chiên vàng đều, nhúng lớp socola Bỉ bóng bẩy và rắc hạnh nhân lát nướng giòn.', '28000.00', '28000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(150, 8, 34, 'Bánh Mì Bơ Tỏi Phô Mai Kiểu Hàn Quốc (Garlic Cheese Bread)', 'banh-mi-bo-toi-han-quoc', 'Bánh mì tròn bổ múi khế bơm ngập kem phô mai béo ngậy, nhúng đẫm sốt bơ tỏi thơm ngát nướng xém vàng giòn tan vỏ.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(151, 8, 34, 'Bánh Red Velvet Phủ Lớp Kem Phô Mai Cream Cheese Mịn', 'red-velvet-cream-cheese', 'Cốt bánh nhung đỏ ẩm mượt mềm tan xen kẽ từng lớp kem phô mai chua béo đặc trưng quyến rũ sang trọng.', '52000.00', '52000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(152, 8, 34, 'Bánh Cupcake Socola Đậm Đà Rắc Hạt Dẻ Cười Pistachio', 'cupcake-socola-pistachio', 'Chiếc cupcake nhỏ xinh xắn vị socola đậm đà, trên chóp bắt bông kem bơ béo ngậy và hạt dẻ cười nghiền thô bùi bùi.', '32000.00', '32000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(153, 8, 34, 'Bánh Quy Bơ Hạnh Nhân Pháp Hộp Thiếc (100g)', 'banh-quy-bo-hanh-nhan', 'Bánh quy bơ giòn tan thơm lừng mùi bơ Pháp cao cấp kết hợp lát hạnh nhân mỏng dính, nhâm nhi cùng tách trà chiều cực phẩm.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(154, 8, 34, 'Bánh Macaron Pháp 5 Vị Sắc Màu (Hộp 5 chiếc)', 'macaron-phap-5-vi', 'Những chiếc macaron chân váy nở xòe xinh xắn đủ 5 vị: Dâu tây, Matcha, Socola đen, Chanh vàng và Vani Madagascar.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(155, 8, 34, 'Bánh Bông Lan Trứng Muối Chà Bông Sốt Phô Mai Kim Sa', 'bong-lan-trung-muoi-cha-bong', 'Cốt bánh bông lan mềm xốp ẩm mịn, ngập tràn chà bông thịt heo tơi xốp, trứng muối bùi bùi và sốt phô mai kim sa chảy thơm nức mũi.', '49000.00', '49000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(156, 8, 34, 'Bánh Danish Đào Tươi Kem Custard Nướng Phồng', 'danish-dao-tuoi-custard', 'Bột bánh đan lớp nở giòn rụm, ở giữa là lớp kem custard vani vàng ươm và nửa quả đào ngâm giòn ngọt thanh mọng.', '42000.00', '42000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(157, 8, 34, 'Bánh Baguette Pháp Truyền Thống Nướng Lò Đá (1 ổ lớn)', 'baguette-phap-truyen-thong', 'Ổ bánh mì dài kiểu Pháp da giòn rụm nứt hoa văn chân chim, ruột xốp dai thơm nồng men chua tự nhiên.', '22000.00', '22000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(158, 8, 34, 'Trà Hoa Cúc Mật Ong Hoa Cà Phê Ấm Áp', 'tra-hoa-cuc-mat-ong-am', 'Những đóa hoa cúc khô hãm nước sôi thơm hương thảo mộc dịu nhẹ, hòa mật ong rừng ngọt thanh giúp an thần thư thái khi ăn bánh ngọt.', '28000.00', '28000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(159, 8, 34, 'Cà Phê Latte Kem Béo Hạt Dẻ Nướng Nóng Hổi', 'latte-hat-de-nuong', 'Espresso thơm nồng đánh cùng sữa tươi nóng tạo bọt nghệ thuật đẹp mắt, hòa quyện si-rô hạt dẻ nướng thơm ấm ngọt ngào.', '42000.00', '42000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(160, 8, 34, 'Trà Bá Tước Earl Grey Hương Cam Bergamot Sang Trọng', 'tra-earl-grey-nong', 'Tách trà quý tộc Anh Quốc tỏa hương thơm cam Bergamot tươi mát, hậu vị chát ngọt êm đềm kết hợp hoàn hảo cùng bánh croissant.', '32000.00', '32000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(161, 9, 34, 'Bánh Pancake Mật Ong Rừng & Dâu Tây Tươi (Set 3 chiếc)', 'pancake-mat-ong-dau-tay', 'Bánh kếp nướng vàng xốp mềm mịn thơm ngậy mùi bơ sữa tươi, rưới mật ong rừng hoa cà phê Đắk Lắk và điểm xuyết dâu tây tươi mọng.', '39000.00', '39000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(162, 9, 34, 'Bánh Mì Chảo Thập Cẩm Đặc Biệt (Pate, Xíu Mại, Bò, Trứng)', 'banh-mi-chao-thap-cam', 'Chảo gang nóng sôi xèo xèo gồm pate gan béo ngậy, thịt bò mềm ngọt xào tỏi, xíu mại sốt cà, trứng ốp la lòng đào và xúc xích nướng.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(163, 9, 34, 'Bánh Mì Xíu Mại Trứng Muối Sốt Cà Cay Nóng Hổi', 'banh-mi-xiu-mai-cay-nong', 'Tô xíu mại nước ngọt thơm gồm 2 viên xíu mại nhân trứng muối mềm mịn, da heo giòn sần sật chan sốt ớt cay ấm chấm bánh mì giòn tan.', '38000.00', '38000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(164, 9, 34, 'Bánh Mì Kẹp Thịt Nguội Bơ Pháp & Dưa Leo Đồ Chua', 'banh-mi-thit-nguoi-bo-phap', 'Bánh mì vỏ giòn tan quét pate gan thơm nức, bơ thơm béo, kẹp thịt nguội jambon, chả lụa quết tiêu, dưa leo và ngò rí đậm đà.', '32000.00', '32000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(165, 9, 34, 'Bánh Mì Heo Quay Giòn Bì Rưới Nước Sốt Đậm Đà', 'banh-mi-heo-quay-gion-bi', 'Thịt heo quay da nổ giòn tan rụm từng tiếng, nạc mỡ đan xen mềm ngọt chan nước sốt heo quay bí truyền đậm đà thơm ấm.', '35000.00', '35000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(166, 9, 34, 'Sandwich Bơ Quả & Trứng Gà Lòng Đào Áp Chảo (Avocado Toast)', 'sandwich-bo-trung-long-dao', 'Bánh mì gối ngũ cốc nướng giòn phết bơ sáp Đắk Lắk nghiền béo bùi, đặt quả trứng gà ốp la lòng đào rắc tiêu đen và ớt bột paprika.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(167, 9, 34, 'Xôi Xéo Gà Xé Nấm Hương Rưới Mỡ Hành Thơm Lừng', 'xoi-xeo-ga-xe-nam-huong', 'Hạt nếp nương đồ vàng óng dẻo quánh, đỗ xanh thái mỏng bùi béo, gà ta xé phay xào nấm hương thơm lừng và rưới mỡ hành hành phi giòn tan.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(168, 9, 34, 'Xôi Mặn Thập Cẩm Chà Bông Lạp Xưởng Trứng Cút', 'xoi-man-thap-cam', 'Hộp xôi nóng hổi ngập tràn topping: lạp xưởng nướng thái lát, chà bông heo tơi xốp, trứng cút chiên giòn, mỡ hành và sốt tương ớt đậm đà.', '35000.00', '35000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(169, 9, 34, 'Bún Bò Huế Chả Cua Giò Heo Cay Nồng Thơm Mắm Ruốc', 'bun-bo-hue-cha-cua-gio-heo', 'Nước dùng bún bò hầm xương ống dậy mùi mắm ruốc Huế và sả phi ớt bột cay nồng, khoanh giò heo ninh mềm dẻo và chả cua biển béo bùi.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(170, 9, 34, 'Hủ Tiếu Nam Vang Tôm Mực Thịt Nạc Thơm Mỡ Tỏi Phi', 'hu-tieu-nam-vang-tom-muc', 'Sợi hủ tiếu dai mềm trụng nóng, tôm sú bóc vỏ ngọt lịm, mực tươi giòn sần sật, thịt nạc xắt mỏng, trứng cút và hành phi thơm lừng bát canh xương.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(171, 9, 34, 'Bánh Canh Cua Đồng Chả Cá Thác Lác Dai Ngon', 'banh-canh-cua-dong-cha-ca', 'Sợi bánh canh bột gạo dẻo dai nấu trong nước dùng riêu cua đồng thơm ngọt tự nhiên, chả cá thác lác Đắk Lắk quết dai giòn rụm.', '48000.00', '48000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(172, 9, 34, 'Cháo Sườn Non Hạt Sen Nấu Nấm Rơm Bổ Dưỡng', 'chao-suon-non-hat-sen', 'Gạo tẻ ninh nhừ sánh mịn như lụa cùng sườn non sụn mềm rục, hạt sen bùi béo và nấm rơm ngọt nước, rắc hành hoa tiêu đen ấm bụng.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(173, 9, 34, 'Cháo Gà Ta Xé Phay Tiêu Sọ Cháo Nhuyễn Mịn', 'chao-ga-ta-xe-phay', 'Cháo nấu từ nước luộc gà ngọt lịm thơm béo, gà ta xé phay rắc lá tía tô, hành hoa và hạt tiêu sọ Đắk Lắk cay ấm giải cảm tuyệt vời.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(174, 9, 34, 'Bánh Cuốn Nóng Tráng Tay Nhân Thịt Mộc Nhĩ Chả Quế', 'banh-cuon-nong-trang-tay', 'Từng lớp bánh mỏng tang tráng tay trên nồi hơi nước nóng hổi, cuộn thịt nạc bằm mộc nhĩ nấm hương giòn sần sật, rắc hành phi giòn và chả quế.', '38000.00', '38000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(175, 9, 34, 'Nui Nấu Sườn Heo & Rau Củ Tươi Ngọt Nước Súp', 'nui-nau-suon-heo-rau-cu', 'Nui vàng luộc mềm nấu cùng sườn heo ninh nhừ, cà rốt, củ cải trắng và bắp ngọt, nước súp trong veo ngọt thanh tự nhiên dễ ăn buổi sáng.', '45000.00', '45000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(176, 9, 34, 'Sữa Bắp Nếp Tươi Nấu Trong Ngày Thơm Béo Mịn', 'sua-bap-nep-tuoi', 'Bắp nếp ngọt thu hoạch tại vườn xay nấu tươi cùng sữa tươi thanh trùng, sánh đặc vàng óng thơm nức nở vị ngô nếp.', '18000.00', '18000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(177, 9, 34, 'Sữa Hạt Sen Đậu Đỏ Dinh Dưỡng Bổ Huyết', 'sua-hat-sen-dau-do', 'Hạt sen tươi xay cùng đậu đỏ ninh mềm và đường phèn thanh ngọt, thức uống ấm áp giàu dinh dưỡng cho bữa sáng tràn đầy năng lượng.', '22000.00', '22000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(178, 9, 34, 'Cà Phê Phin Sữa Đá Đậm Chất Buôn Ma Thuột', 'ca-phe-phin-sua-da-bmt', 'Hạt cà phê Robusta chín đỏ hái từ nông trường Buôn Ma Thuột rang mộc xay mịn nhỏ giọt qua phin nhôm truyền thống, hòa sữa đặc béo ngọt sánh đậm.', '25000.00', '25000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(179, 9, 34, 'Trà Gừng Mật Ong Ấm Bụng Khởi Đầu Ngày Mới', 'tra-gung-mat-ong-am-bung', 'Gừng sẻ tươi giã dập nấu sôi hòa mật ong hoa cà phê nguyên chất, thức uống thanh lọc cơ thể ấm nồng đánh thức giác quan.', '20000.00', '20000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(180, 9, 34, 'Nước Cam Tươi Vắt Ép Mật Ong Nguyên Chất (Ly Lớn)', 'nuoc-cam-tuoi-vat-mat-ong', 'Cam sành miền Tây mọng nước vắt tươi 100% không pha nước lọc, ngọt thanh nhờ mật ong hoa rừng bổ sung vitamin C dồi dào.', '28000.00', '28000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(181, 10, 31, 'Gà Rán Giòn Sốt Cay Hàn Quốc (Hot Spicy Crispy Chicken)', 'ga-ran-gion-sot-cay', 'Gà tươi rán giòn rụm lớp vỏ ngoài, phủ đẫm sốt cay nồng đặc chế kiểu Hàn Quốc, thịt mềm ngọt mọng nước bên trong.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(182, 10, 31, 'Gà Rán Sốt Đậu Tỏi Nồng Đượm (Soy Garlic Chicken)', 'ga-ran-sot-dau-toi', 'Miếng gà chiên giòn áo lớp sốt đậu tương lên men và tỏi phi thơm nồng, vị ngọt mặn hài hòa cực bắt vị.', '78000.00', '78000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(183, 10, 31, 'Gà Rán Phủ Phô Mai Tuyết Trắng Béo Ngậy (Snow Cheese Chicken)', 'ga-ran-pho-mai-tuyet', 'Lớp bột phô mai tuyết ngọt bùi thơm lừng phủ kín miếng gà rán vàng rộm vừa vớt từ chảo dầu nóng hổi.', '82000.00', '82000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(184, 10, 31, 'Burger Bò Nướng Sốt Tiêu Đen Phú Quốc Phô Mai', 'burger-bo-sot-tieu-den', 'Bò nướng than hoa quyện sốt tiêu đen cay ấm nồng nàn, phô mai Cheddar béo ngậy và hành tây xào caramen.', '72000.00', '72000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(185, 10, 31, 'Burger Bò Nướng BBQ Thịt Ba Chỉ Xông Khói (Bacon King)', 'burger-bo-bacon-king', 'Sự kết hợp giữa 2 dải bacon giòn rụm, miếng bò nướng lửa thơm khói và lớp phô mai Mỹ chảy ngập tràn.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(186, 10, 31, 'Burger Phi Lê Gà Giòn Sốt Cay Phô Mai Chảy', 'burger-phi-le-ga-cay-pho-mai', 'Phi lê gà tẩm bột chiên xù giòn tan rụm, rưới sốt ớt cay đỏ au và lát phô mai Mozzarella chảy dẻo.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(187, 10, 31, 'Cơm Gà Rán Giòn Sốt Cà Ri Nhật Bản Kèm Canh Rong Biển', 'com-ga-ran-ca-ri-nhat', 'Miếng gà rán giòn rụm thái lát đặt trên dĩa cơm trắng nóng dẻo, rưới nước sốt cà ri Nhật củ cải cà rốt đậm đà thơm béo.', '68000.00', '68000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(188, 10, 31, 'Cơm Gà Xào Nấm Sốt Teriyaki Đậm Đà Kiểu Nhật', 'com-ga-xao-nam-teriyaki', 'Thịt gà đùi xào săn cùng nấm hương tươi và sốt teriyaki bóng bẩy, rắc mè trắng rang bùi thơm đưa cơm.', '62000.00', '62000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(189, 10, 31, 'Đùi Gà Rán Vàng Giòn Rụm Lớp Vỏ Xù (1 chiếc đùi lớn)', 'dui-ga-ran-gion-rum-lon', 'Chiếc đùi gà tỏi cỡ bự chiên xù giòn tan rụm, thịt bên trong trắng mềm mọng nước không khô xác.', '36000.00', '36000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(190, 10, 31, 'Cánh Gà Chiên Bơ Tỏi Thơm Nức Mũi (Hộp 3 cánh)', 'canh-ga-chien-bo-toi-3-canh', 'Cánh gà chiên giòn xóc bơ tỏi tươi phi vàng, thơm nức mũi chấm sốt tương ớt ngọt cực bắt mồi.', '59000.00', '59000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(191, 10, 31, 'Khoai Lang Kén Lắc Phô Mai Béo Bùi Giòn Vỏ', 'khoai-lang-ken-lac-pho-mai', 'Khoai lang kén vàng ươm thơm béo vị nước cốt dừa nướng giòn rụm bên ngoài dẻo ngọt bên trong, lắc bột phô mai bùi thơm.', '32000.00', '32000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(192, 10, 31, 'Khoai Tây Lắc Phô Mai & Bột Rong Biển (Hộp Lớn)', 'khoai-tay-lac-rong-bien-pho-mai', 'Khoai tây chiên giòn xốc trong túi cùng bột phô mai cam béo ngậy và rong biển nướng thơm phức.', '38000.00', '38000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(193, 10, 31, 'Phô Mai Viên Chiên Giòn Nhân Mozzarella Kéo Sợi (5 viên)', 'pho-mai-vien-chien-gion', 'Viên phô mai tròn vo chiên phồng vàng rụm, cắn vào dòng phô mai dẻo quánh kéo sợi dài vô tận béo ngậy ngất ngây.', '39000.00', '39000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(194, 10, 31, 'Bánh Tart Phô Mai Nướng Xém Vàng (Cheese Tart)', 'banh-tart-pho-mai-nuong', 'Vỏ tart bơ giòn rụm ôm nhân kem phô mai chua béo nướng vàng xém, món tráng miệng ngọt dịu sau khi ăn gà rán.', '30000.00', '30000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(195, 10, 31, 'Mì Ý Gà Rán Giòn Sốt Cà Chua Phô Mai Đút Lò', 'mi-y-ga-ran-sot-ca-chua', 'Sợi mì Ý sốt cà chua đút lò phủ phô mai, ăn kèm miếng gà rán giòn rụm nóng hổi cắt lát.', '75000.00', '75000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(196, 10, 31, 'Combo Gà Rán 2 Miếng + Khoai Tây Chiên + Coca-Cola', 'combo-ga-ran-2-mieng-khoai-coca', 'Combo no nê chuẩn chỉnh: 2 miếng gà rán giòn cay, 1 gói khoai tây chiên vàng và 1 ly Coca-Cola mát lạnh sảng khoái.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(197, 10, 31, 'Combo Burger Bò Tiêu Đen + 1 Miếng Gà + 1 Ly Nước', 'combo-burger-bo-tieu-1-ga-nuoc', 'Set ăn thịnh soạn kết hợp cả burger bò nướng sốt tiêu và gà rán giòn rụm kèm nước giải khát.', '105000.00', '105000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(198, 10, 31, 'Salad Gà Rán Sốt Mè Rang Nhật Bản Thanh Mát', 'salad-ga-ran-sot-me-rang', 'Xà lách tươi xanh, dưa leo, cà chua bi giòn ngọt trộn cùng những lát gà rán cắt hạt lựu và sốt mè rang béo bùi.', '49000.00', '49000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(199, 10, 31, 'Trà Chanh Dây Hạt Chia Mát Lạnh Giải Nhiệt', 'tra-chanh-day-hat-chia', 'Nước cốt chanh dây tươi chua thanh thơm ngát hòa quyện hạt chia nở giòn, thức uống giải ngấy số 1 khi ăn đồ chiên rán.', '25000.00', '25000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(200, 10, 31, 'Kem Tươi Vani Ốc Quế Giòn Tan (Vanilla Soft Cone)', 'kem-tuoi-vani-oc-que', 'Cây kem tươi vani xoắn ốc mềm mịn ngọt dịu mát lạnh trên chiếc bánh ốc quế nướng giòn rụm thơm bơ.', '15000.00', '15000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(201, 11, 35, 'Salad Ức Gà Áp Chảo Rau Củ Sốt Mè Rang Nhật Bản', 'salad-uc-ga-ap-chao', 'Ức gà phi lê áp chảo tiêu đen không dầu mềm mọng, xà lách Romaine, cà chua bi, dưa leo, ngô ngọt và sốt mè rang béo bùi chuẩn eat-clean.', '52000.00', '52000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(202, 11, 35, 'Salad Bơ Sáp Đắk Lắk Trứng Gà Luộc & Hạt Điều Rang', 'salad-bo-sap-trung-luoc', 'Bơ sáp Buôn Ma Thuột béo ngậy cắt lát, quả trứng gà ta luộc lòng đào, hạt điều rang thơm giòn và sốt sữa chua chanh mật ong thanh nhẹ.', '55000.00', '55000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(203, 11, 35, 'Salad Cá Hồi Na Uy Áp Chảo Sốt Chanh Dây Olive', 'salad-ca-hoi-chanh-day', 'Khúc lườn cá hồi Na Uy áp chảo xém vàng thơm béo, giàu Omega-3, hòa cùng xà lách tím, cà chua bi và sốt chanh dây dầu olive nguyên chất.', '85000.00', '85000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(204, 11, 35, 'Salad Bò Úc Nướng Thảo Mộc Sốt Dầu Giấm Balsamic Ý', 'salad-bo-uc-balsamic', 'Thịt thăn bò Úc thái lát mỏng ướp hương thảo áp chảo chín tới mọng nước, trộn rau rocket, cà chua bi và giấm đen Balsamic đậm vị Ý.', '68000.00', '68000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(205, 11, 35, 'Salad Tôm Sú Nướng Bơ Tỏi & Rau Rocket Cà Chua Bi', 'salad-tom-su-nuong-rocket', 'Tôm sú tươi bóc nõn nướng bơ tỏi thơm ngào ngạt, rau mầm cải, xà lách giòn và sốt cam tươi thanh mát tràn đầy sức sống.', '65000.00', '65000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(206, 11, 35, 'Cơm Gạo Lứt Ức Gà Nướng Mật Ong Rừng & Bông Cải Xanh', 'com-gao-lut-uc-ga-nuong', 'Cơm gạo lứt dẻo thơm nấu chín tới giàu chất xơ, ức gà nướng mật ong ít calo và đĩa bông cải xanh cà rốt luộc ngọt thanh.', '58000.00', '58000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(207, 11, 35, 'Cơm Gạo Lứt Cá Hồi Na Uy Áp Chảo Măng Tây Nướng', 'com-gao-lut-ca-hoi-mang-tay', 'Bữa ăn giàu đạm lành mạnh với cá hồi phi lê áp chảo bơ lạt, măng tây non nướng giòn ngọt và cơm gạo lứt hạt sen bùi béo.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(208, 11, 35, 'Cơm Gạo Lứt Thăn Bò Áp Chảo Rau Củ Xào Dầu Hào Nhạt', 'com-gao-lut-than-bo', 'Thăn bò mềm xào ớt chuông, hành tây và nấm đông cô với lượng muối thấp theo chế độ giảm mỡ tăng cơ lành mạnh.', '68000.00', '68000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(209, 11, 35, 'Cơm Tấm Gạo Lứt Sườn Cốt Lết Ít Muối Ăn Kèm Canh Rau', 'com-tam-gao-lut-suon-nuong', 'Biến tấu cơm tấm truyền thống trên nền gạo lứt tím than, sườn cốt lết nướng than không phẩm màu và nhiều rau dưa tươi mát.', '58000.00', '58000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(210, 11, 35, 'Poke Bowl Cá Hồi Tươi Rau Mầm & Hạt Quinoa Dinh Dưỡng', 'poke-bowl-ca-hoi-quinoa', 'Tô Poke chuẩn Hawaii đầy màu sắc: cá hồi sống cắt hạt lựu, quả bơ, ngô ngọt, đậu nành edamame, hạt diêm mạch Quinoa và sốt ponzu thanh mát.', '89000.00', '89000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(211, 11, 35, 'Poke Bowl Đậu Hũ Non Áp Chảo & Bơ Sáp Sốt Teriyaki (Chay)', 'poke-bowl-dau-hu-chay', 'Món chay healthy thanh lọc cơ thể với đậu hũ non nướng vàng thơm, bơ sáp, củ cải đường, dưa leo và gạo lứt dẻo thơm.', '55000.00', '55000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(212, 11, 35, 'Bánh Mì Cuộn Wrap Ức Gà Rau Cải Kale & Sốt Sữa Chua', 'wrap-uc-ga-cai-kale', 'Bánh cuộn Tortilla nguyên cám gói ghém ức gà nướng áp chảo, lá cải xoăn kale giòn mát và sốt sữa chua Hy Lạp nhẹ bụng.', '49000.00', '49000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(213, 11, 35, 'Bánh Mì Cuộn Wrap Bò Úc Rau Củ & Phô Mai Ít Béo', 'wrap-bo-uc-rau-cu', 'Thịt bò Úc xắt sợi áp chảo thơm nức cuộn cùng xà lách xoăn, cà chua bi và phô mai ít béo tốt cho tim mạch.', '55000.00', '55000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(214, 11, 35, 'Tô Canh Bí Đỏ Thịt Nạc Bằm Nấu Nấm Tươi Dinh Dưỡng', 'canh-bi-do-thit-nac-nam', 'Bí đỏ hồ lô ngọt bùi ninh nhừ cùng nạc heo bằm và nấm rơm tươi, vị ngọt thanh tự nhiên tốt cho thị lực và não bộ.', '25000.00', '25000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(215, 11, 35, 'Tô Canh Cải Xoong Nấu Tôm Tươi Ngọt Nước Tự Nhiên', 'canh-cai-xoong-tom-tuoi', 'Rau cải xoong giòn ngọt nấu cùng tôm tươi băm dối, vị ngọt lịm từ biển cả giúp giải nhiệt và bổ sung sắt dồi dào.', '28000.00', '28000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(216, 11, 35, 'Súp Gà Rau Củ Nấm Hương Thanh Nhẹ Ít Calo', 'sup-ga-rau-cu-nam-huong', 'Súp nấu từ nước luộc gà không mỡ, thịt ức gà xé, bắp ngọt, nấm tuyết và lòng trắng trứng gà mềm mướt ấm bụng.', '28000.00', '28000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(217, 11, 35, 'Nước Ép Cần Tây Táo Xanh Detox Tươi Mát Thải Độc', 'nuoc-ep-can-tay-tao-xanh', 'Cần Tây hữu cơ ép tươi cùng táo xanh giòn ngọt và lát gừng tươi, không thêm đường, công thức detox thanh lọc cơ thể chuẩn khoa học.', '35000.00', '35000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(218, 11, 35, 'Nước Ép Củ Dền Cà Rốt Cam Vàng Sáng Da Đẹp Dáng', 'nuoc-ep-cu-den-ca-rot-cam', 'Màu đỏ ruby rực rỡ từ củ dền Đà Lạt, cà rốt ngọt lịm và cam vàng mọng nước, giàu chất chống oxy hóa giúp làn da rạng rỡ.', '35000.00', '35000.00', 1, 0, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(219, 11, 35, 'Sinh Tố Bơ Chuối Hạt Chia Sữa Hạt Yến Mạch (Không Đường)', 'sinh-to-bo-chuoi-yen-mach', 'Bơ sáp Buôn Ma Thuột xay cùng chuối tiêu chín tự nhiên và sữa yến mạch thơm bùi, thức uống giàu năng lượng cho người tập gym.', '42000.00', '42000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(220, 11, 35, 'Sữa Chua Hy Lạp Trái Cây Tươi & Hạt Granola Nướng Giòn', 'sua-chua-hy-lap-granola', 'Sữa chua Hy Lạp lên men đặc sánh dẻo giàu protein, phủ dâu tây tươi, việt quất và hạt granola nướng mật ong giòn rụm.', '45000.00', '45000.00', 1, 1, 15, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(221, 12, 33, 'Mì Ý Spaghetti Bò Bằm Sốt Cà Chua Bolognese Truyền Thống', 'spaghetti-bo-bam-bolognese-y-jut', 'Sợi mì luộc mềm dai vừa tới ngập tràn sốt thịt bò bằm hầm cà chua bi tươi ngọt thanh, rắc phô mai Parmesan béo bùi và lá húng quế Ý.', '79000.00', '79000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(222, 12, 33, 'Mì Ý Hải Sản Tôm Sú Mực Ống Sốt Pesto Húng Tây Xanh', 'spaghetti-hai-san-pesto-y-jut', 'Hương vị biển cả Địa Trung Hải! Sốt pesto xanh ngát thơm nồng lá basil và hạt thông béo bùi, tôm sú giòn ngọt và mực tươi xào bơ tỏi.', '89000.00', '89000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(223, 12, 33, 'Mì Ý Sốt Kem Tươi Nấm & Thịt Ba Chỉ Xông Khói Carbonara', 'spaghetti-carbonara-bacon', 'Nước sốt kem tươi sánh vàng béo ngậy nấu cùng lòng đỏ trứng gà, thịt ba chỉ hun khói áp chảo giòn thơm và nấm mỡ tươi.', '85000.00', '85000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(224, 12, 33, 'Mì Ý Cua Biển Sốt Kem Cà Chua Hồng (Pink Sauce Crab Spaghetti)', 'spaghetti-cua-bien-pink-sauce', 'Thịt cua biển tươi gỡ miếng đảo cùng sốt kem hồng sánh mịn hòa quyện giữa vị chua thanh của cà chua và vị béo của kem whipping cream.', '99000.00', '99000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(225, 12, 33, 'Mì Ý Tôm Tươi Xào Tỏi Ớt Dầu Olive (Spaghetti Aglio e Olio)', 'spaghetti-aglio-olio-tom', 'Món mì kinh điển nước Ý mộc mạc mà quyến rũ: Sợi mì đảo cùng dầu olive extra virgin, tỏi phi vàng ruộm, ớt hiểm cay nồng và tôm tươi giòn ngọt.', '75000.00', '75000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(226, 12, 33, 'Mì Ý Thăn Bò Nướng Sốt Tiêu Đen Cay Nhẹ', 'spaghetti-bo-sot-tieu-den', 'Từng lát thịt thăn bò mềm thơm nướng xém cạnh, rưới sốt tiêu đen hầm vang đỏ cay ấm nồng nàn trên đĩa mì Ý nóng sốt.', '85000.00', '85000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(227, 12, 33, 'Mì Dẹt Fettuccine Sốt Kem Nấm Truffle Đen Quý Phái', 'fettuccine-sot-nam-truffle', 'Sợi mì dẹt bản lớn dẻo dai đẫm sốt nấm Truffle đen thơm ngát đặc trưng ẩm thực quý tộc Ý, rắc nấm mỡ xào bơ tỏi.', '95000.00', '95000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(228, 12, 33, 'Lasagna Bò Băm Đút Lò Phô Mai Kéo Sợi Béo Ngậy', 'lasagna-bo-bam-dut-lo', 'Từng lá bột mì xếp lớp xen kẽ sốt bò băm Bolognese, sốt bechamel béo mịn và phủ ngập phô mai Mozzarella đút lò vàng ruộm thơm lừng.', '89000.00', '89000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(229, 12, 33, 'Nui Xoắn Fusilli Đút Lò Sốt Phô Mai Cheddar & Mozzarella', 'nui-xoan-dut-lo-cheddar', 'Nui xoắn giữ trọn sốt phô mai béo ngậy đút lò cháy xém mặt, vị mặn mòi thơm phức quyến rũ từng thìa.', '75000.00', '75000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(230, 12, 33, 'Nui Ống Xào Bò Băm Nấm Rơm Sốt Cà Chua Phô Mai', 'nui-ong-xao-bo-bam-nam', 'Nui ống luộc mềm xào cùng thịt bò bằm ngấm sốt cà chua tươi và nấm rơm ngọt nước, món ăn ngon miệng hấp dẫn.', '69000.00', '69000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(231, 12, 33, 'Mì Ý Ravioli Bánh Xếp Nhân Phô Mai Ricotta Rau Chân Vịt', 'ravioli-ricotta-rau-chan-vit', 'Bánh bột mì xếp thủ công nhồi phô mai Ricotta bùi ngậy và rau chân vịt thanh mát, tắm trong sốt bơ xô thơm lừng.', '89000.00', '89000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(232, 12, 33, 'Pizza Margherita Truyền Thống Phô Mai Mozzarella & Lá Basil', 'pizza-margherita-y-jut', 'Chiếc pizza mang màu cờ nước Ý: Sốt cà chua đỏ au, phô mai Mozzarella tươi trắng tinh và lá húng tây xanh ngát nướng lò củi giòn xốp.', '99000.00', '99000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(233, 12, 33, 'Pizza Xúc Xích Ý & Ớt Chuông Nướng Lò Than Đá', 'pizza-xuc-xich-ot-chuong', 'Xúc xích Ý đậm đà thái lát kết hợp ớt chuông Đà Lạt 3 màu nướng ngọt giòn và phô mai kéo sợi thơm phức.', '115000.00', '115000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(234, 12, 33, 'Bánh Mì Nướng Bơ Tỏi Phô Mai Mozzarella Đút Lò', 'banh-mi-bo-toi-pho-mai-y-jut', 'Từng lát baguette nướng giòn rụm thơm bơ tỏi, phủ lớp phô mai Mozzarella đút lò vàng ruộm kéo sợi dài bất tận.', '35000.00', '35000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(235, 12, 33, 'Soup Nấm Rừng Kem Tươi Nóng Hổi Hương Thảo Mộc', 'soup-nam-rung-kem-tuoi', 'Nấm mỡ, nấm hương xào bơ xay nhuyễn cùng kem tươi béo ngậy, dùng nóng thơm lừng chấm cùng bánh mì nướng giòn.', '35000.00', '35000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(236, 12, 33, 'Salad Caesar Rau Xanh Ức Gà Nướng Phô Mai Bào Parmesan', 'salad-caesar-y-jut', 'Xà lách Romaine giòn ngọt trộn sốt Caesar cá cơm truyền thống, bánh mì vụn nướng giòn và phô mai Parmesan bào.', '55000.00', '55000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(237, 12, 33, 'Khoai Tây Nghiền Đút Lò Phô Mai Vàng Óng Kéo Sợi', 'khoai-tay-nghien-dut-lo-pho-mai', 'Khoai tây hấp mịn màng trộn bơ lạt, phủ phô mai Mozzarella đút lò thơm nức mũi béo ngậy tan trên đầu lưỡi.', '39000.00', '39000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(238, 12, 33, 'Bánh Panna Cotta Sốt Dâu Rừng Ý Mềm Mịn Thanh Mát', 'panna-cotta-dau-rung', 'Món tráng miệng Ý danh tiếng mềm mịn tan biến trong miệng như thạch sữa béo ngậy, sốt dâu rừng đỏ mọng chua ngọt quyến rũ.', '39000.00', '39000.00', 1, 1, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(239, 12, 33, 'Trà Táo Quế Nóng Hương Thảo Mộc Ấm Áp', 'tra-tao-que-nong', 'Trà đen ủ cùng thanh quế già thơm lừng và lát táo tươi, hòa chút mật ong ngọt dịu làm ấm lòng thực khách.', '28000.00', '28000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(240, 12, 33, 'Nước Khoáng Có Ga San Pellegrino Vị Chanh Vàng (Chai)', 'san-pellegrino-chanh-vang', 'Dòng nước khoáng có ga đóng chai danh tiếng nước Ý, sảng khoái với bọt khí li ti và hương chanh vàng thanh nhã.', '35000.00', '35000.00', 1, 0, 20, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(241, 13, 34, 'Khoai Tây Lắc Phô Mai Béo Ngậy Giòn Rụm (Hộp Lớn)', 'khoai-tay-lac-pho-mai-le-duan', 'Khoai tây cọng chiên vàng giòn rụm, lắc đều tay trong túi giấy với ngập tràn bột phô mai cam thơm bùi ngọt mặn hấp dẫn.', '35000.00', '35000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(242, 13, 34, 'Khoai Tây Lắc Rong Biển Sấy Giòn Sốt Mayonnaise', 'khoai-tay-lac-rong-bien-le-duan', 'Khoai chiên giòn tan lắc cùng bột rong biển sấy cay nhẹ thơm nồng phong cách Nhật Bản, chấm sốt mayo béo ngậy.', '35000.00', '35000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(243, 13, 34, 'Khoai Lang Lắc Xí Muội Chua Ngọt Giòn Bùi', 'khoai-lang-lac-xi-muoi', 'Khoai lang vàng Đắk Lắk dẻo ngọt bùi chiên giòn vỏ, xóc bột xí muội ô mai chua chua ngọt ngọt mặn mặn cực cuốn.', '32000.00', '32000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(244, 13, 34, 'Khoai Môn Lệ Phố Chiên Giòn Nhân Trứng Muối Tán Nhuyễn', 'khoai-mon-le-pho-trung-muoi', 'Từng viên khoai môn lệ phố tròn xoe tím mộng mơ chiên xù vàng óng, cắn ngập nhân trứng muối sữa dừa béo bùi ngọt dịu.', '38000.00', '38000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(245, 13, 34, 'Phô Mai Que Mozzarella Kéo Sợi Dài Bất Tận (Hộp 4 que)', 'pho-mai-que-keo-soi-le-duan', 'Lõi phô mai Mozzarella nguyên chất béo ngậy được tẩm 3 lớp bột chiên giòn vàng ruộm, kéo sợi dài cả cánh tay chấm tương cà chua ngọt.', '42000.00', '42000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(246, 13, 34, 'Xúc Xích Đức Nướng Than Hoa Phủ Sốt Cay Phô Mai (2 chiếc)', 'xuc-xich-duc-nuong-than', 'Xúc xích Đức khía hoa nướng than hoa đượm khói giòn sần sật, rưới sốt cay phô mai và tương ớt đậm đà.', '38000.00', '38000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(247, 13, 34, 'Bánh Gà Phô Mai Kéo Sợi Vỏ Giòn Rụm (Set 3 chiếc)', 'banh-ga-pho-mai-keo-soi', 'Thịt ức gà tươi xay nêm nếm gia vị đậm đà ôm trọn viên phô mai Mozzarella, tẩm bột chiên xù vàng ươm giòn tan.', '39000.00', '39000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(248, 13, 34, 'Bánh Tráng Nướng Trứng Cút Thịt Bằm Phô Mai Đà Lạt', 'banh-trang-nuong-da-lat', 'Pizza Việt Nam danh tiếng! Bánh tráng nướng than hoa giòn rụm với trứng cút, thịt heo bằm, tép khô, mỡ hành, sốt bơ và phô mai béo ngậy.', '25000.00', '25000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(249, 13, 34, 'Bánh Tráng Cuộn Sốt Bơ Bò Khô Trứng Cút (Hộp 5 cuốn)', 'banh-trang-cuon-sot-bo', 'Bánh tráng dẻo tôm phơi sương cuộn bò khô xé cay, trứng cút chiên, rau răm, xoài xanh và chan ngập sốt bơ trứng gà vàng ươm béo ngậy.', '28000.00', '28000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(250, 13, 34, 'Gà Viên Popcorn Giòn Rụm Lắc Bột Ớt Paprika Cay Nhẹ', 'ga-popcorn-le-duan', 'Gà viên không xương tẩm ướp chiên giòn tan từng viên vừa miệng, lắc bột ớt ngọt Paprika thơm nồng hấp dẫn.', '39000.00', '39000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
INSERT INTO `products` (`id`, `restaurant_id`, `category_id`, `name`, `slug`, `description`, `base_price`, `discount_price`, `is_available`, `is_featured`, `prep_time_minutes`, `created_at`, `updated_at`) VALUES
(251, 13, 34, 'Mực Viên Chiên Nước Mắm Bơ Tỏi Giòn Sần Sật (Hộp 6 viên)', 'muc-vien-chien-nuoc-mam', 'Chả mực tươi quết nhuyễn chiên vàng ruộm ngào qua sốt nước mắm tỏi ớt kẹo sệt cay the the thơm nức.', '38000.00', '38000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(252, 13, 34, 'Nem Chua Rán Phố Cổ Hà Nội Giòn Cay (Phần 5 chiếc)', 'nem-chua-ran-pho-co', 'Nem chua tẩm bột chiên xù giòn tan bên ngoài dẻo dai béo ngậy bên trong, chấm tương ớt Mường Khương chuẩn vị Hà Thành.', '45000.00', '45000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(253, 13, 34, 'Chả Cá Viên Chiên Nước Mắm Tỏi Ớt Đậm Đà (Hộp 10 viên)', 'ca-vien-chien-nuoc-mam', 'Cá viên chiên phồng xù đảo trên chảo sốt mắm đường tỏi ớt kẹo quánh và rau muống giòn, món ăn vặt tuổi thơ gây nghiện.', '32000.00', '32000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(254, 13, 34, 'Bắp Xào Bơ Tép Khô Mỡ Hành Thơm Lừng', 'bap-xao-bo-tep-mo-hanh', 'Hạt bắp Mỹ vàng ngọt mọng nước xào bơ Tường An thơm ngào ngạt, tép khô mặn mặn ngọt ngọt và mỡ hành xanh mướt.', '25000.00', '25000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(255, 13, 34, 'Bánh Hành Tây Chiên Giòn Xù Kiểu Mỹ (Onion Rings Le Duan)', 'hanh-tay-chien-gion-le-duan', 'Khoanh hành tây ngọt giòn tẩm bột chiên xù vàng óng ả chấm sốt tương cà ngọt chua thanh mát.', '32000.00', '32000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(256, 13, 34, 'Xíu Mại Viên Hấp Trứng Cút Nóng Hổi Chấm Bánh Mì (3 viên)', 'xiu-mai-vien-trung-cut', 'Viên thịt xíu mại to mập ôm trọn trứng cút bên trong, ninh trong nước sốt cà chua ấm nồng thơm mùi hành ngò.', '35000.00', '35000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(257, 13, 34, 'Da Gà Chiên Giòn Rụm Chấm Muối Tiêu Chanh Ớt', 'da-ga-chien-gion-rum', 'Da gà làm sạch lọc bỏ hoàn toàn mỡ dưới da, chiên phồng xốp giòn rụm tan ngay trong miệng, rắc muối ớt cay tê tê.', '35000.00', '35000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(258, 13, 34, 'Trà Tắc Xí Muội Khổng Lồ Mát Lạnh (Ly Lớn 700ml)', 'tra-tac-xi-muoi-khong-lo', 'Ly trà tắc khổng lồ thơm ngào ngạt cốt quất tươi hòa quyện trái xí muội mặn ngọt chua thanh sảng khoái đánh bay cơn khát.', '22000.00', '22000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(259, 13, 34, 'Trà Sữa Trân Châu Sợi Dừa Nướng Thơm Béo Bùi', 'tra-sua-dua-nuong', 'Trà sữa thơm ngậy mùi dừa nướng Bến Tre, topping dừa nướng sấy giòn rụm rắc trên mặt ly uống vui miệng cực kỳ.', '35000.00', '35000.00', 1, 0, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53'),
(260, 13, 34, 'Tàu Hũ Trân Châu Đường Đen Cốt Dừa Béo Ngậy', 'tau-hu-tran-chau-duong-den', 'Tàu hũ non núng nính mềm mịn tan ngay trên đầu lưỡi, chan nước cốt dừa béo ngậy và trân châu đường đen dẻo nóng ngọt ngào.', '25000.00', '25000.00', 1, 1, 12, '2026-11-12 14:53:53', '2026-11-12 14:53:53')
