('products', '[{"id":"prod-1","name":"Burger Bò Nướng Phô Mai Tan Chảy (Double Cheese)","slug":"burger-bo-nuong-pho-mai","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"Burger & Gà Rán","price":69000,"oldPrice":89000,"rating":4.9,"reviews":142,"time":"15 - 20 phút","image":"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600&auto=format&fit=crop&q=80","isBestSeller":true,"description":"Thịt bò Úc 100% nướng lửa than hoa thơm nức mũi, kẹp phô mai Cheddar béo ngậy, sốt BBQ đặc chế và rau xà lách tươi giòn.","toppings":[{"name":"Thêm phô mai lát Cheddar","price":10000},{"name":"Thịt xông khói giòn (Bacon)","price":15000},{"name":"Trứng ốp la lòng đào","price":8000}],"status":"Đang bán"},{"id":"prod-2","name":"Burger Bò Nướng Lửa Than Hoa (Whopper Classic)","slug":"burger-bo-whopper-classic","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"Burger & Gà Rán","price":89000,"oldPrice":109000,"rating":4.8,"reviews":110,"time":"15 - 20 phút","image":"https://images.unsplash.com/photo-1550547660-d9450f859349?w=600&auto=format&fit=crop&q=80","isBestSeller":true,"description":"Thịt bò nướng lửa cỡ lớn đậm vị khói phương Tây, lát cà chua đỏ mọng và dưa chuột muối giòn tan.","toppings":[{"name":"Gấp đôi thịt bò nướng","price":35000},{"name":"Thêm sốt BBQ khói","price":5000},{"name":"Phô mai lát","price":10000}],"status":"Đang bán"},{"id":"prod-3","name":"Burger Bò Tắm Sốt Nấm Truffle Đen Thượng Hạng","slug":"burger-bo-sot-nam-truffle","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"Burger & Gà Rán","price":99000,"oldPrice":125000,"rating":4.9,"reviews":95,"time":"15 - 20 phút","image":"https://images.unsplash.com/photo-1586190848861-99aa4a171e90?w=600&auto=format&fit=crop&q=80","isBestSeller":true,"description":"Sốt kem nấm Truffle đen quý hiếm phủ trọn miếng bò nướng mọng nước, hòa quyện sốt nấm xào thơm béo.","toppings":[{"name":"Thêm sốt Truffle thơm ngậy","price":15000},{"name":"Nấm xào bơ tỏi","price":12000},{"name":"Phô mai Thụy Sĩ","price":12000}],"status":"Đang bán"},{"id":"prod-4","name":"Burger Bò Trứng Lòng Đào Thịt Ba Chỉ Xông Khói (Bacon)","slug":"burger-bo-trung-long-dao-bacon","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"Burger & Gà Rán","price":82000,"oldPrice":99000,"rating":4.7,"reviews":88,"time":"15 - 20 phút","image":"https://images.unsplash.com/photo-1551782450-a2132b4ba21d?w=600&auto=format&fit=crop&q=80","isBestSeller":false,"description":"Sự kết hợp hoàn hảo giữa thịt bò nướng than, trứng gà lòng đào tan chảy và 2 dải bacon áp chảo giòn rụm.","toppings":[{"name":"Thêm 2 dải Bacon giòn","price":18000},{"name":"Trứng ốp la lòng đào","price":8000},{"name":"Khoai tây chiên ăn kèm","price":15000}],"status":"Đang bán"},{"id":"prod-5","name":"Burger Bò Cay Sốt Ớt Jalapeno Mễ Tây Cơ","slug":"burger-bo-cay-jalapeno","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"Burger & Gà Rán","price":75000,"oldPrice":89000,"rating":4.8,"reviews":76,"time":"15 - 20 phút","image":"https://images.unsplash.com/photo-1594212699903-ec8a3eca50f5?w=600&auto=format&fit=crop&q=80","isBestSeller":false,"description":"Dành cho tín đồ ăn cay! Ớt Jalapeno Mexico cay nồng kết hợp sốt chipotle mayo bốc khói kích thích vị giác.","toppings":[{"name":"Thêm ớt Jalapeno ngâm giòn","price":8000},{"name":"Sốt cay bốc khói","price":6000},{"name":"Phô mai Cheddar","price":10000}],"status":"Đang bán"},{"id":"prod-6","name":"Burger Bò 3 Tầng Siêu Khủng (Triple Beast Burger)","slug":"burger-bo-3-tang-sieu-khung","restaurantId":"res-1","restaurant":"Burger King Station","restaurantName":"Burger King Station","categoryId":"burger","category":"B